function raven_get_icon( string $name ): string {
	return raven_get_icons()[ $name ] ?? '';
}

function raven_icon_options(): array {
	$options = [ '' => __( 'None', 'raven' ) ];
	foreach ( raven_get_icons() as $name => $svg ) {
		$options[ $name ] = ucwords( str_replace( '-', ' ', $name ) );
	}
	return $options;
}
